#include <iostream>
#include <string>
#include <vector>

bool isLetter(char c)
{
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
}

void summarise(const std::vector<std::string>& words,
               int& letters, std::string& longest)
{
    letters = 0;
    longest = words[0];

    for (const std::string& word : words)
    {
        for (char c : word)
        {
            if (isLetter(c)) ++letters;
        }

        if (word.size() > longest.size()) longest = word;
    }
}

int main()
{
    std::vector<std::string> words{};
    std::string word{};

    while (std::cin >> word) words.push_back(word);

    if (words.empty())
    {
        std::cout << "words 0\n";
        std::cout << "letters 0\n";
        std::cout << "longest none\n";
        return 0;
    }

    int letters{};
    std::string longest{};
    summarise(words, letters, longest);

    std::cout << "words " << words.size() << "\n";
    std::cout << "letters " << letters << "\n";
    std::cout << "longest " << longest << "\n";

    return 0;
}
